#!/usr/bin/env node
/* eslint-disable no-console */
/**
 * Synchronizes src/components/ApiExplorer/openapi.json with the OpenAPI spec
 * generated by the mos-api repository (https://github.com/mos-nas/mos-api).
 *
 * The mos-api app builds its spec at runtime with `swagger-jsdoc` from JSDoc
 * annotations in src/routes/*.js plus the base config in src/config/swagger.js
 * (which already exports the assembled spec). Because swagger-jsdoc only *parses*
 * the route files (it never require()s them), installing just `swagger-jsdoc` is
 * enough to reproduce the exact spec deterministically — no running MOS instance
 * required.
 *
 * Usage:
 *   node scripts/sync-openapi.js              # write the regenerated spec
 *   node scripts/sync-openapi.js --check      # exit 1 if the committed spec differs
 *   node scripts/sync-openapi.js --ref v1.2   # use a different mos-api ref (branch/tag/sha)
 */
const fs = require('fs');
const os = require('os');
const path = require('path');
const {execSync} = require('child_process');

const REPO = 'https://github.com/mos-nas/mos-api.git';
const SWAGGER_JSDOC_VERSION = '^6.3.0'; // must match mos-api/package.json
const TARGET = path.resolve(__dirname, '..', 'src', 'components', 'ApiExplorer', 'openapi.json');

// Cross-shell quoting: paths here contain no embedded double quotes or spaces.
const q = (s) => `"${s}"`;

function parseArgs(argv) {
  const out = {check: false, ref: 'master', trigger: 'manual'};
  for (let i = 2; i < argv.length; i++) {
    const a = argv[i];
    if (a === '--check') out.check = true;
    else if (a === '--ref') out.ref = argv[++i];
    else if (a.startsWith('--ref=')) out.ref = a.slice(6);
    else if (a === '--trigger') out.trigger = argv[++i];
    else if (a.startsWith('--trigger=')) out.trigger = a.slice(10);
    else if (a === '-h' || a === '--help') {
      console.log('Usage: node scripts/sync-openapi.js [--check] [--ref <git-ref>] [--trigger schedule|manual]');
      process.exit(0);
    }
  }
  return out;
}

function run(cmd, opts = {}) {
  return execSync(cmd, {stdio: ['ignore', 'pipe', 'pipe'], encoding: 'utf8', ...opts})
    .toString()
    .trim();
}

function generate(opts) {
  const tmp = path.join(os.tmpdir(), `mos-api-sync-${process.pid}-${Date.now()}`);
  fs.rmSync(tmp, {recursive: true, force: true});
  fs.mkdirSync(tmp, {recursive: true});
  try {
    console.log(`\u25B6 Cloning mos-api (ref: ${opts.ref}) ...`);
    run(`git clone --depth 1 ${REPO} ${q(tmp)}`);
    if (opts.ref && opts.ref !== 'master') {
      run(`git -C ${q(tmp)} fetch --depth 1 origin ${q(opts.ref)}`);
      run(`git -C ${q(tmp)} checkout FETCH_HEAD`);
    }
    const sha = run(`git -C ${q(tmp)} rev-parse HEAD`);
    console.log(`\u25B6 Checked out ${sha.slice(0, 10)}`);

    // Minimal package.json so npm installs swagger-jsdoc into <tmp>/node_modules.
    fs.writeFileSync(
      path.join(tmp, 'package.json'),
      JSON.stringify({name: 'mos-api-sync', version: '0.0.0', private: true}, null, 2) + '\n',
    );
    console.log(`\u25B6 Installing swagger-jsdoc@${SWAGGER_JSDOC_VERSION} ...`);
    run(`npm install --no-audit --no-fund --no-package-lock swagger-jsdoc@${SWAGGER_JSDOC_VERSION}`, {
      cwd: tmp,
    });

    // swagger.js resolves its `apis` glob relative to process.cwd(), so chdir.
    const prevCwd = process.cwd();
    process.chdir(tmp);
    let spec;
    try {
      spec = require(path.join(tmp, 'src', 'config', 'swagger.js'));
    } finally {
      process.chdir(prevCwd);
    }

    // Drop any non-serializable bits, then add OpenAPI extension metadata
    // (legal x- fields; ignored by ApiExplorer) so the sync state is visible.
    spec = JSON.parse(JSON.stringify(spec));
    spec['x-synced-from'] = sha;
    spec['x-synced-ref'] = opts.ref;
    spec['x-synced-trigger'] = opts.trigger;
    const syncedAt = new Date();
    spec['x-synced-at'] = syncedAt.toISOString();
    spec['x-synced-at-display'] = new Intl.DateTimeFormat('de-AT', {
      timeZone: 'Europe/Vienna',
      day: '2-digit',
      month: '2-digit',
      year: 'numeric',
      hour: '2-digit',
      minute: '2-digit',
      timeZoneName: 'shortOffset',
    }).format(syncedAt);

    return {spec, sha};
  } finally {
    fs.rmSync(tmp, {recursive: true, force: true});
  }
}

function summarize(oldSpec, newSpec) {
  const oldPaths = oldSpec ? Object.keys(oldSpec.paths || {}) : [];
  const newPaths = Object.keys(newSpec.paths || {});
  const oldTags = oldSpec && oldSpec.tags ? oldSpec.tags.map((t) => t.name) : [];
  const newTags = newSpec.tags ? newSpec.tags.map((t) => t.name) : [];
  const addedP = newPaths.filter((p) => !oldPaths.includes(p));
  const removedP = oldPaths.filter((p) => !newPaths.includes(p));
  const addedT = newTags.filter((t) => !oldTags.includes(t));
  const removedT = oldTags.filter((t) => !newTags.includes(t));
  console.log(`  paths: ${oldPaths.length} -> ${newPaths.length}`);
  if (addedP.length) console.log(`  + paths: ${addedP.join(', ')}`);
  if (removedP.length) console.log(`  - paths: ${removedP.join(', ')}`);
  if (addedT.length) console.log(`  + tags: ${addedT.join(', ')}`);
  if (removedT.length) console.log(`  - tags: ${removedT.join(', ')}`);
}

const opts = parseArgs(process.argv);
const {spec, sha} = generate(opts);
const content = JSON.stringify(spec, null, 2) + '\n';

let oldSpec = null;
if (fs.existsSync(TARGET)) {
  try {
    oldSpec = JSON.parse(fs.readFileSync(TARGET, 'utf8'));
  } catch (_) {
    /* ignore parse errors; treat as missing */
  }
}

if (opts.check) {
  const existing = fs.existsSync(TARGET) ? fs.readFileSync(TARGET, 'utf8') : '';
  if (existing === content) {
    console.log('\u2714 openapi.json is up to date (no drift).');
    process.exit(0);
  }
  console.log('\u2716 Drift detected: committed openapi.json differs from generated spec.');
  summarize(oldSpec, spec);
  process.exit(1);
}

fs.writeFileSync(TARGET, content);
console.log(`\u2714 Wrote ${path.relative(process.cwd(), TARGET)}`);
console.log(`  synced from mos-api@${sha.slice(0, 10)} (${opts.ref}) at ${spec['x-synced-at-display']} [${opts.trigger}]`);
summarize(oldSpec, spec);